From 232aaa42ed3d136672881d1bd1563aa29945fdbf Mon Sep 17 00:00:00 2001
From: Mark Robert Miller <markrmiller@apache.org>
Date: Wed, 19 Dec 2012 16:41:18 +0000
Subject: [PATCH] SOLR-4218: SolrTestCaseJ4 throws NPE when closing the core
 (on the afterClass method)

git-svn-id: https://svn.apache.org/repos/asf/lucene/dev/trunk@1423932 13f79535-47bb-0310-9956-ffa450edef68

diff --git a/solr/core/src/java/org/apache/solr/handler/component/HttpShardHandlerFactory.java b/solr/core/src/java/org/apache/solr/handler/component/HttpShardHandlerFactory.java
index 32b173be2fc..9410f959a87 100644
--- a/solr/core/src/java/org/apache/solr/handler/component/HttpShardHandlerFactory.java
+++ b/solr/core/src/java/org/apache/solr/handler/component/HttpShardHandlerFactory.java
@@ -162,12 +162,16 @@ public class HttpShardHandlerFactory extends ShardHandlerFactory implements Plug
     }

     try {
-      defaultClient.getConnectionManager().shutdown();
+      if(defaultClient != null) {
+        defaultClient.getConnectionManager().shutdown();
+      }
     } catch (Throwable e) {
       SolrException.log(log, e);
     }
     try {
-      loadbalancer.shutdown();
+      if(loadbalancer != null) {
+        loadbalancer.shutdown();
+      }
     } catch (Throwable e) {
       SolrException.log(log, e);
     }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug is caused by the potential for a NullPointerException (NPE) when the `defaultClient` or `loadbalancer` objects are null during the shutdown process in the `HttpShardHandlerFactory` class. This can occur if these objects were not properly initialized or if they were set to null before the shutdown method is called, leading to an attempt to invoke methods on a null reference.

        Commit message:
        SOLR-4218: SolrTestCaseJ4 throws NPE when closing the core
 (on the afterClass method)

git-svn-id: https://svn.apache.org/repos/asf/lucene/dev/trunk@1423932 13f79535-47bb-0310-9956-ffa450edef68  

        Patch:

   @Override
   public void close() {
     try {
       ExecutorUtil.shutdownAndAwaitTermination(commExecutor);
     } catch (Throwable e) {
       SolrException.log(log, e);
     }

     try {
-      defaultClient.getConnectionManager().shutdown();
+      if(defaultClient != null) {
+        defaultClient.getConnectionManager().shutdown();
+      }
     } catch (Throwable e) {
       SolrException.log(log, e);
     }
     try {
-      loadbalancer.shutdown();
+      if(loadbalancer != null) {
+        loadbalancer.shutdown();
+      }
     } catch (Throwable e) {
       SolrException.log(log, e);
     }

   }
 }


